code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    objects = []
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        # These objects are rectangular frames; their complete perimeter defines the box.
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = all(grid[r0][c] == color and grid[r1][c] == color for c in range(c0,c1+1)) and all(grid[r][c0] == color and grid[r][c1] == color for r in range(r0,r1+1))
        if perimeter:
            mask = [[grid[r][c] == color for c in range(c0+1,c1)] for r in range(r0+1,r1)]
            objects.append((color,r0,r1,c0,c1,mask))
    out = [[0]*w for _ in range(h)]
    for obj in objects:
        color,r0,r1,c0,c1,mask = obj
        ih, iw = r1-r0-1, c1-c0-1
        group = [x for x in objects if x[2]-x[1]-1 == ih and x[4]-x[3]-1 == iw]
        # A pattern is retained and copied only when at least one matching frame exists.
        if len(group) < 2 or not any(any(any(row) for row in x[5]) for x in group):
            continue
        for x in group:
            col,a,b,d,e,pat = x
            for c in range(d,e+1):
                out[a][c] = col
                out[b][c] = col
            for r in range(a,b+1):
                out[r][d] = col
                out[r][e] = col
            # Pattern-bearing members remain as-is; empty matching frames receive the template.
            source_mask = next(y[5] for y in group if any(any(row) for row in y[5]))
            if not any(any(row) for row in pat):
                for i in range(ih):
                    for j in range(iw):
                        if source_mask[i][j]:
                            out[a+1+i][d+1+j] = col
            else:
                for i in range(ih):
                    for j in range(iw):
                        if pat[i][j]:
                            out[a+1+i][d+1+j] = col
    return out
